describe('.canMessageUser()', () => {
	beforeEach(setChatPrivacy);
	after(setChatPrivacy);

	it('should allow messages when both lists are empty and incoming chats are enabled', async () => {
		await Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid);
		await Messaging.canMessageUser(mocks.users.baz.uid, mocks.users.herp.uid);
	});

	it('should reject messages when incoming chats are disabled', async () => {
		await setChatPrivacy({ disableIncomingMessages: true, chatAllowList: [String(mocks.users.herp.uid)] });
		await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), {
			message: '[[error:chat-restricted]]',
		});
	});

	it('should reject messages from senders on the deny list', async () => {
		await setChatPrivacy({ chatDenyList: [String(mocks.users.herp.uid)] });
		await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), {
			message: '[[error:chat-restricted]]',
		});
	});

	it('should allow only listed senders when the allow list is non-empty', async () => {
		await setChatPrivacy({ chatAllowList: [String(mocks.users.bar.uid)] });
		await Messaging.canMessageUser(mocks.users.bar.uid, mocks.users.baz.uid);
		await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), {
			message: '[[error:chat-restricted]]',
		});
	});

	it('should give the deny list precedence over the allow list', async () => {
		const senderUid = String(mocks.users.herp.uid);
		await setChatPrivacy({ chatAllowList: [senderUid], chatDenyList: [senderUid] });
		await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), {
			message: '[[error:chat-restricted]]',
		});
	});

	it('should not use follows as an implicit allow list', async () => {
		await User.follow(mocks.users.baz.uid, mocks.users.herp.uid);
		try {
			await setChatPrivacy({ chatAllowList: [String(mocks.users.bar.uid)] });
			await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), {
				message: '[[error:chat-restricted]]',
			});
		} finally {
			await User.unfollow(mocks.users.baz.uid, mocks.users.herp.uid);
		}
	});

	it('should allow administrators and global moderators through privacy settings', async () => {
		await setChatPrivacy({
			disableIncomingMessages: true,
			chatDenyList: [String(mocks.users.foo.uid), String(mocks.users.herp.uid)],
		});
		await Messaging.canMessageUser(mocks.users.foo.uid, mocks.users.baz.uid);
		await Groups.join('Global Moderators', mocks.users.herp.uid);
		try {
			await Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid);
		} finally {
			await Groups.leave('Global Moderators', mocks.users.herp.uid);
		}
	});

	it('should report an explicit block before any privacy restriction', async () => {
		await setChatPrivacy({ disableIncomingMessages: true, chatDenyList: [String(mocks.users.herp.uid)] });
		await User.blocks.add(mocks.users.herp.uid, mocks.users.baz.uid);
		try {
			await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), {
				message: '[[error:chat-user-blocked]]',
			});
		} finally {
			await User.blocks.remove(mocks.users.herp.uid, mocks.users.baz.uid);
		}
	});

	it('should report an explicit block even for an administrator', async () => {
		// Privileged users cannot be blocked through the UI, but an existing block must still take precedence.
		const key = `uid:${mocks.users.baz.uid}:blocked_uids`;
		await db.sortedSetAdd(key, Date.now(), mocks.users.foo.uid);
		User.blocks._cache.del(String(mocks.users.baz.uid));
		try {
			await setChatPrivacy({ disableIncomingMessages: true });
			await assert.rejects(Messaging.canMessageUser(mocks.users.foo.uid, mocks.users.baz.uid), {
				message: '[[error:chat-user-blocked]]',
			});
		} finally {
			await db.sortedSetRemove(key, mocks.users.foo.uid);
			User.blocks._cache.del(String(mocks.users.baz.uid));
		}
	});

	it('should reject a muted sender before starting a chat', async () => {
		await User.setUserField(mocks.users.herp.uid, 'mutedUntil', Date.now() + (2 * 60 * 1000));
		try {
			await assert.rejects(Messaging.canMessageUser(mocks.users.herp.uid, mocks.users.baz.uid), (err) => {
				assert(err.message.startsWith('[[error:user-muted-for-minutes,'));
				return true;
			});
		} finally {
			await db.deleteObjectField(`user:${mocks.users.herp.uid}`, 'mutedUntil');
		}
		});
	});

	it('should not allow messaging room if user is muted', async () => {
		const twoMinutesFromNow = Date.now() + (2 * 60 * 1000);
		const twoHoursFromNow = Date.now() + (2 * 60 * 60 * 1000);
		const roomId = 0;

		await User.setUserField(mocks.users.herp.uid, 'mutedUntil', twoMinutesFromNow);
		await assert.rejects(Messaging.canMessageRoom(mocks.users.herp.uid, roomId), (err) => {
			assert(err.message.startsWith('[[error:user-muted-for-minutes,'));
			return true;
		});

		await User.setUserField(mocks.users.herp.uid, 'mutedUntil', twoHoursFromNow);
		await assert.rejects(Messaging.canMessageRoom(mocks.users.herp.uid, roomId), (err) => {
			assert(err.message.startsWith('[[error:user-muted-for-hours,'));
			return true;
		});
		await db.deleteObjectField(`user:${mocks.users.herp.uid}`, 'mutedUntil');
		await assert.rejects(Messaging.canMessageRoom(mocks.users.herp.uid, roomId), {
			message: '[[error:no-room]]',
		});
	});
});

