'use strict';

const nconf = require('nconf');
const winston = require('winston');
const _ = require('lodash');
const jwt = require('jsonwebtoken');
const util = require('util');

const user = require('../../user');
const languages = require('../../languages');
const meta = require('../../meta');
const plugins = require('../../plugins');
const notifications = require('../../notifications');
const db = require('../../database');
const helpers = require('../helpers');
const slugify = require('../../slugify');

const settingsController = module.exports;

const chatPrivacySettings = {
	title: '[[user:chat-privacy]]',
	content: `
		<p class="form-text">[[user:chat-privacy-help]]</p>
		<div class="form-check form-switch mb-3">
			<input class="form-check-input" type="checkbox" role="switch" id="disableIncomingMessages" data-property="disableIncomingMessages">
			<label class="form-check-label" for="disableIncomingMessages">[[user:disable-incoming-messages]]</label>
		</div>
		<div class="mb-3">
			<label class="form-label" for="chatAllowListSearch">[[user:chat-allow-list]]</label>
			<input class="form-control form-control-sm" type="text" id="chatAllowListSearch" placeholder="[[user:chat-list-search]]" autocomplete="off">
			<div id="chatAllowListUsers" class="d-flex flex-wrap gap-2 mt-2"></div>
			<p class="form-text">[[user:chat-allow-list-help]]</p>
		</div>
		<div class="mb-3">
			<label class="form-label" for="chatDenyListSearch">[[user:chat-deny-list]]</label>
			<input class="form-control form-control-sm" type="text" id="chatDenyListSearch" placeholder="[[user:chat-list-search]]" autocomplete="off">
			<div id="chatDenyListUsers" class="d-flex flex-wrap gap-2 mt-2"></div>
			<p class="form-text">[[user:chat-deny-list-help]]</p>
		</div>`,
};

settingsController.get = async function (req, res, next) {
	const { userData } = res.locals;
	if (!userData) {
		return next();
	}
	const [settings, languagesData] = await Promise.all([
		user.getSettings(userData.uid),
		languages.list(),
	]);

	userData.settings = settings;
	userData.languages = languagesData;
	if (userData.isAdmin && userData.isSelf) {
		userData.acpLanguages = _.cloneDeep(languagesData);
	}

	const data = await plugins.hooks.fire('filter:user.customSettings', {
		settings: settings,
		customSettings: [],
		uid: req.uid,
	});
	if (!meta.config.disableChat) {
		const uids = [...new Set([...settings.chatAllowList, ...settings.chatDenyList])];
		const users = await user.getUsersFields(uids, ['username']);
		userData.chatPrivacyUsers = Object.fromEntries(uids.map((uid, index) => [
			uid, users[index] && users[index].username ? users[index].username : uid,
		]));
		data.customSettings.unshift(chatPrivacySettings);
	}

	const [notificationSettings, routes, bsSkinOptions] = await Promise.all([
		getNotificationSettings(userData),
		getHomePageRoutes(userData),
		getSkinOptions(userData),
	]);

	userData.customSettings = data.customSettings;
	userData.homePageRoutes = routes;
	userData.bootswatchSkinOptions = bsSkinOptions;
	userData.notificationSettings = notificationSettings;
	userData.disableEmailSubscriptions = meta.config.disableEmailSubscriptions;

	userData.dailyDigestFreqOptions = [
